p=argparse.ArgumentParser();p.add_argument('--evidence-dir',type=Path,required=True);p.add_argument('--archive',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.evidence_dir.resolve();out=a.output.resolve();out.mkdir(parents=True,exist_ok=True)
