if archive_hash!='293f5dc04a5612622c30310ca461a9e43070f4995589e5355427ee54e4702bf7':raise ValueError('Archive is not the assessed input')
with zipfile.ZipFile(a.archive) as z:assert z.testzip() is None and len(z.namelist())==83
for line in (root/'SHA256SUMS').read_text().splitlines():
 h,n=line.split('  ',1);f=(root/n).resolve();assert f.is_relative_to(root) and hashlib.sha256(f.read_bytes()).hexdigest()==h
r=json.loads((root/'record.json').read_text());cases={f.stem:json.loads(f.read_text()) for f in (root/'cases').glob('*.json')};qx=json.loads((root/'qx-transfer/qx-audit.json').read_text());controls=json.loads((root/'observer-and-time-controls.json').read_text())
t=datetime.now(timezone.utc);stamp={'utc':t.isoformat(),'melbourne':t.astimezone(ZoneInfo('Australia/Melbourne')).isoformat()}
def pred(m,x):
 z=(np.asarray(x)-m['origin'])/m['scale'];c=m['coefficients']
 return c[0]+c[1]*z**c[2] if m['model']=='offset_power' else np.exp(c[0]+c[1]*z) if m['model']=='exponential' else np.polynomial.polynomial.polyval(z,c)
def select(kind,n):return next(c for c in cases.values() if c['parameters']['field']==kind and c['parameters']['nodes']==n and c['parameters']['steps']==960 and c['parameters']['duration']==1)
audit=[];fits=[]
for b in r['blocks']:
 frozen=json.loads((root/'blocks'/b['id']/'frozen-fit.json').read_text());assert frozen['rows']==b['development'];assert not {v['level'] for v in b['development']}&{v['level'] for v in b['validation']};assert all(b['frozen_at']['utc']<v['measured_at']['utc'] for v in b['validation'])
 for fm,m in zip(frozen['models'],b['models']):
  assert all(m[k]==v for k,v in fm.items());res=np.array([pred(m,v['x'])-v['y'] for v in b['validation']]);assert np.isclose(float(max(abs(res))),m['validation_max_abs_error'],atol=1e-16,rtol=1e-10)
 for s in b['selection_journal']:
  v=next(v for v in b['development'] if v['level']==s['level']);assert s['recorded_at']['utc']<v['measured_at']['utc']
 audit.append({'block':b['id'],'frozen_coefficients_match':True,'new_validation_disjoint':True,'freeze_precedes_new_validation':True,'choice_precedes_measurement':True,'validation_residuals_recomputed':True})
 m=b['models'][0];fits.append({'block':b['id'],'primary_model':m['model'],'response':b['response'],'fresh_validation_max_fraction':m['validation_max_abs_error'],'fresh_validation_max_percentage_points':100*m['validation_max_abs_error'],'prediction_pass':b['prediction_pass'],'stop_reason':b['stop_reason']})
for name,h in r['environment']['code_sha256'].items():assert hashlib.sha256((root/'code'/name).read_bytes()).hexdigest()==h
fm=json.loads((root/'field-manifest.json').read_text());assert len(fm['files'])==len(cases)==35
for v in fm['files']:
 c=cases[Path(v['file']).stem];assert v['sha256']==c['state']['sha256'] and v['bytes']==c['state']['bytes']
for c in cases.values():
 o=c.get('observer')
 if o:assert abs(o['total_observed_error']**2-o['evolution_observed_error']**2-o['observer_baseline_error']**2-o['normalized_cross_term'])<1e-15
 trace=c['trace'];defect=trace[-1]['energy']-trace[0]['energy']+np.trapezoid([v['outward_flux'] for v in trace],x=[v['time'] for v in trace]);assert np.isclose(defect,c['poynting_balance']['defect'],atol=1e-13)

fig,axes=plt.subplots(2,2,figsize=(12,9),layout='constrained');color={'hopfion':'#215f91','packet':'#bd650c'}
for kind in ['hopfion','packet']:
 b=next(v for v in r['blocks'] if v['id']==kind+'-spacing');rows=sorted(b['development']+b['validation'],key=lambda v:v['x']);fine=select(kind,129)['observer']['evolution_observed_error'];x=[v['x'] for v in rows];y=[v['y']/fine for v in rows];axes[0,0].plot(x,y,'o-',color=color[kind],ms=3,label=kind.title());vals=b['validation'];axes[0,0].scatter([v['x'] for v in vals],[v['y']/fine for v in vals],color=color[kind],marker='s',s=35,zorder=4)
fine_h=8/129;x=np.linspace(fine_h,8/49,100);axes[0,0].plot(x,(x/fine_h)**2,'--',color='#777',label='h² reference (anchored at N129)');axes[0,0].set(xscale='log',yscale='log',title='Controlled spacing trend approaches second order',xlabel='h (model units; log scale)',ylabel='Evolution error / N129 evolution error');axes[0,0].legend(fontsize=8)
labels=['Evolution','Interpolation baseline','Total'];pos=np.arange(3)
for offset,kind in [(-.18,'hopfion'),(.18,'packet')]:
 o=select(kind,129)['observer'];values=[100*o[k] for k in ['evolution_observed_error','observer_baseline_error','total_observed_error']];axes[0,1].bar(pos+offset,values,width=.34,color=color[kind],label=kind.title())
axes[0,1].set_xticks(pos,labels);axes[0,1].set(yscale='log',title='N129: observer error remains material',ylabel='Relative field L2 (%)');axes[0,1].legend();axes[0,1].text(.02,.02,'Separate vector norms; bars are not additive',transform=axes[0,1].transAxes,fontsize=8)
for offset,kind in [(-.18,'hopfion'),(.18,'packet')]:
 b=next(v for v in r['blocks'] if v['id']==kind+'-spacing');m=b['models'][0];values=[abs(float(pred(m,v['x']))-v['y'])/5e-6 for v in b['validation']];axes[1,0].bar(pos+offset,values,width=.34,color=color[kind],label=kind.title())
axes[1,0].axhline(1,color='#b43636',ls='--',label='Declared prediction limit');axes[1,0].set_xticks(pos,['N57','N81','N113']);axes[1,0].set(yscale='log',title='Hopfion N81 misses the frozen-model prediction check',ylabel='Absolute residual / declared limit');axes[1,0].legend(fontsize=8)
for c in controls:
 o=cases[c['base_case']]['observer'];rows=[o]+c['observer_refinement'];change=[100*(v['evolution_observed_error']/o['evolution_observed_error']-1) for v in rows];axes[1,1].plot([v['observer_nodes'] for v in rows],change,'o-',label=c['field'].title()+' N'+str(c['nodes']))
axes[1,1].set(title='Saved-state observer refinement is not monotonic',xlabel='Observer nodes per axis',ylabel='Evolution metric change from observer33 (%)');axes[1,1].set_xticks([33,49,65]);axes[1,1].legend(fontsize=8)
for ax in axes.flat:ax.grid(alpha=.2)
fig.suptitle('35-case dependency continuation — completed with explicit qualifications',fontsize=14);fig.savefig(out/'assessment-curves.png',dpi=300);buf=io.StringIO();fig.savefig(buf,format='svg');svg=buf.getvalue();svg=svg[svg.index('<svg'):];plt.close(fig)

mesh=[]
for n in [49,65,97,129]:
 h=select('hopfion',n)['observer'];p=select('packet',n)['observer'];mesh.append({'N':n,'h':8/n,'hopfion_evolution_percent':100*h['evolution_observed_error'],'hopfion_interpolation_percent':100*h['observer_baseline_error'],'hopfion_total_percent':100*h['total_observed_error'],'packet_evolution_percent':100*p['evolution_observed_error'],'packet_interpolation_percent':100*p['observer_baseline_error'],'packet_total_percent':100*p['total_observed_error']})
orders={}
for kind in ['hopfion','packet']:
 ns=[49,65,97,129];ys=[select(kind,n)['observer']['evolution_observed_error'] for n in ns];orders[kind]=[{'coarse':a,'fine':b,'apparent_p':float(np.log(ya/yb)/np.log(b/a))} for a,b,ya,yb in zip(ns[:-1],ns[1:],ys[:-1],ys[1:])]
qxgroup=next(v for v in qx['temporal_groups'] if v['distinct_levels']==3);qr=sorted(qxgroup['rows'],key=lambda v:-v['dt']);ratio=(qr[0]['speed_error']-qr[1]['speed_error'])/(qr[1]['speed_error']-qr[2]['speed_error'])
packet=[c for c in cases.values() if c['parameters']['field']=='packet'];summary={'assessment_at':stamp,'source_archive_sha256':archive_hash,'run_id':'20261114t000026z-1620e2b1','source_commit':r['environment']['source_commit'],'run_started':r['recorded_at'],'run_finished':r['finished_at'],'completed_configurations':35,'reused_parent_states':sum('reused_from' in c for c in cases.values()),'fresh_integrations':sum('reused_from' not in c for c in cases.values()),'integrity':{'zip_entries':83,'compact_hashes_verified':82,'raw_full_arrays_present':False,'field_manifest_declarations':35,'declared_bytes':sum(v['bytes'] for v in fm['files']),'scope':'Scalar, code/provenance and compact-payload assessment; no independent raw-state hash/CRC or field replay.'},'fit_results':fits,'mesh_table':mesh,'apparent_orders':orders,'audit':audit,'packet_controls_recomputed':{'max_fourier_exact_error':max(c['fourier']['exact_error'] for c in packet),'max_modified_energy_drift':max(c['modified_energy_relative_drift'] for c in packet),'max_discrete_divergence_change':max(c['max_discrete_divergence_change_normalized'] for c in packet)},'qx':{'survey_cases':15,'matched_groups':10,'excluded_admissions':3,'q3_temporal_difference_ratio':ratio,'q3_descriptive_apparent_order':float(np.log2(ratio))},'disposition':'Packet mesh prediction/refinement passed; Hopfion mesh prediction/refinement remains unresolved; duration prediction passed with final individual tolerances met but no two-successive-round certificate. Controlled h dependence strongly supports a spatial error explanation in the tested range. Observer integration needs calibration before further fitting or optimal-grid selection.'}
(out/'assessment.json').write_text(json.dumps(summary,indent=2)+'\n')
for name,rows in [('mesh-summary.csv',mesh),('fit-summary.csv',fits)]:
 with (out/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
ft=''.join(f"<tr><td>{v['block']}</td><td>{v['primary_model']}</td><td>{v['fresh_validation_max_percentage_points']:.7g}</td><td>{v['prediction_pass']}</td><td>{v['stop_reason']}</td></tr>" for v in fits)
mt=''.join(f"<tr><td>{v['N']}</td><td>{v['hopfion_evolution_percent']:.6g}</td><td>{v['hopfion_total_percent']:.6g}</td><td>{v['packet_evolution_percent']:.6g}</td><td>{v['packet_total_percent']:.6g}</td></tr>" for v in mesh)
body=f'''<h1>Dependency continuation: outcome assessment</h1><p><strong>Disposition:</strong> completed with useful numerical evidence and retained failures. Controlled spacing refinement strongly supports the previously suspected spatial-error explanation. Packet spacing passes the declared prediction/refinement checks; Hopfion spacing does not. The duration fit passes fresh prediction, and its last individual refinement check passes, but its two-successive-round stopping condition remains open. No physical-model, SF motion, isolation, charge or quantum gate is closed.</p><p>Assessment UTC: {html.escape(stamp['utc'])}; Melbourne: {html.escape(stamp['melbourne'])}. Source run starts {html.escape(json.dumps(r['recorded_at']))} and finishes {html.escape(json.dumps(r['finished_at']))}: approximately 55 min 48 s. The source checkout reports commit <code>{r['environment']['source_commit']}</code>. This is local provenance, not a live verification of GitHub PR or release state.</p><h2>Integrity and execution</h2><p>All 83 ZIP entries pass CRC checks and all 82 declared compact hashes match. Archived module hashes match the environment receipt. Frozen models, disjoint new validation, choice-before-measurement chronology and validation residuals were checked. Recorded Poynting integrals and vector-decomposition scalar identities were recomputed. There are 35 recorded configurations: six new localized-duration cases, sixteen Hopfion meshes, nine packet meshes and four separate time anchors. Two N65/T1 states were reused from the verified parent; thirty-three new integrations ran. Packet early stopping accounts for the unused four slots under the 39-case maximum.</p><p>The 35 local field files are declared at 1,407,315,126 bytes (1.311 GiB). Their manifest entries match the case receipts, but their bytes are absent from the compact ZIP. This assessment does not independently replay those arrays or verify their NPZ CRCs. Retain them for local replay and a separately verified archive.</p>{svg}<h2>Declared fit outcomes</h2><table><tr><th>Study</th><th>Primary model</th><th>Max fresh residual (percentage points)</th><th>Prediction pass</th><th>Stop</th></tr>{ft}</table><p>The fixed prediction limit is 5e-6 as a fractional response, or 0.0005 percentage points. Hopfion spacing misses at N81: 7.86517e-6, about 1.57 times the declared limit. N57 and N113 pass. The N81 residual is about 0.0643% of its local field-error value, so this is a narrow empirical-prediction failure, not evidence of a failed integration or physical instability. The threshold and failed result remain unchanged.</p><h2>Spatial dependence is now measured</h2><table><tr><th>N</th><th>Hopfion evolution (%)</th><th>Hopfion total observed (%)</th><th>Packet evolution (%)</th><th>Packet total observed (%)</th></tr>{mt}</table><p>Here every mesh uses fixed L=8, T=1, dt=1/960, phase/orientation/startup/boundary prescription, and one fixed 33³ physical observer. Evolution error is a matched vector difference through the same interpolation operator. Total observed error includes interpolation baseline and its vector cross term; the norms are not additive.</p><p>From N49 to N129, evolution error drops by factors 6.454 (Hopfion) and 6.888 (packet). Pairwise apparent powers over 49→65→97→129 are 1.867, 1.938, 1.969 for Hopfion and 1.988, 1.995, 1.998 for packet. These are consistent with an approach to second-order spatial behaviour in this tested range. A cubic empirical interpolant does not imply a third-order solver. The matched-observer response is different from the earlier native error: reusing the same N65 fields with a different observation norm is not an improved physical trajectory.</p><p>The unconstrained offset-power candidates yield p≈1.833 for Hopfion and p≈1.984 for packet, with negative fitted constant offsets. Those negative h→0 limits are not physically meaningful error predictions. They indicate that an unconstrained finite-range response curve should not be extrapolated to the continuum or used to forecast an optimal grid. Future candidates may impose a nonnegative floor or use a pure-power model, with development selection and fresh validation preserved; do not retrospectively switch the primary model after inspecting its withheld failure.</p><h2>Observer calibration is the next economical numerical task</h2><p>At N129, Hopfion evolution/interpolation/total errors are 0.49155% / 0.33860% / 0.59456%. Packet values are 0.023253% / 0.048924% / 0.055968%. The packet's interpolation baseline exceeds its evolution error. This makes observer quality material to plotted fields and total-error claims.</p><p>Saved-state observer grids 33,49,65 do not show monotonic convergence. Hopfion N49 evolution error spans 1.12187e-4 as a fraction, larger than both the 5e-6 fit limit and the observed N81 prediction miss. At N129, the Hopfion evolution metric spans 1.81196e-6; the interpolation baseline varies by about 4.47% relative. The packet N129 interpolation baseline varies by about 6.22% relative. Near agreement of the nested 33/65 observers therefore does not establish converged quadrature.</p><p>Alignment of observer samples with native interpolation cells is a plausible contributor, supported by the nonmonotonic saved-state checks, but it has not been isolated as the cause of the Hopfion fit failure. The global Hopfion cubic is convex throughout the fitted h interval: its inflection lies outside it, near h=0.311. Internal curvature-change flags instead come from local divided differences. Treat them as potential observation/residual structure until they survive an independent observer-resolution/phase check, rather than immediately as physical inflections.</p><p>First reprocess the saved states with a controlled denser physical observer and an independent noncommensurate sampling check, holding the physical field fixed. Alternatively test a cell-aware integration rule as a separately labelled observation method. Predeclare an observation-error budget below the fit residual limit. Keep this diagnostic study separate from physical mesh refinement. Only after the instrument is adequate should a revised fit be frozen and checked on new, pre-reserved physical grids. Old validation grids have now been inspected and become development context for a revised model.</p><h2>Time and constraint checks</h2><p>Doubling dt at the coarse/fine anchors changes the primary evolution metric by at most about 0.104% relative, against a more-than-sixfold improvement from spatial refinement. This supports time-step error being subordinate for these cases, without proving the time-continuum limit. The analytical half-step startup and synchronized diagnostic remain part of the measured convention.</p><p>All eleven packet cases retain strong numerical controls: exact Fourier errors at most 1.13e-15, modified-energy drift at most 4.44e-16, and discrete-divergence change at most 2.70e-13. Initial normalized divergence decreases approximately with h²: Hopfion 0.05853→0.008531; packet 0.003632→0.0005244. Its small evolution change preserves the initial discretization residual rather than making it zero. Native cube sizes vary with h, so their raw flux defects remain auxiliary; no fixed-region flux spatial-order certificate is inferred here.</p><h2>Localized duration: one confirmation remains</h2><p>The three new adaptive durations were 0.541667,0.608333,0.575. Their premeasurement prediction residuals were all below 1e-6. The feature-width checks after the first two were 3.646% of the full span, and after the third 2.604%, below the 3% target. Thus the last point passes both individual criteria, but it is the first qualifying round and the contract requires two consecutive rounds. The budget-exhausted label is correct. All three new validation points pass, with maximum residual 4.57000e-7. The cubic inflection estimate is now near T=0.56105 and remains an empirical location.</p><p>If the formal stopping certificate is needed, use one additional focused adaptive confirmation, retaining the same physical controls and reserving new validation first. Do not repeat the whole time curve or relax the two-round rule. The point-density limiter suppressed feature bonuses in a region already containing several samples; future acquisition should balance density with bracket width and unresolved observation error instead of treating density alone as sufficient resolution.</p><h2>Qx transfer and the wider plan</h2><p>The Qx phase audited fifteen existing S5-B-010 cases: six screen passes, six screen failures, three rejected admissions. Twelve admitted trajectories form ten strictly matched groups; only one Q3 group has three time-step levels. Rejected Q4 admissions stay outside motion fits, Q7 preparation remains unresolved, and Q1 remains parked. There is no new SF evolution in this tranche.</p><p>The matched Q3 z-direction speed errors at dt=.02,.01,.005 are 1.057321835%,1.057321720%,1.057321713%. Their tiny differences have ratio ≈15.949, descriptively consistent with fourth-order temporal differences, while the speed discrepancy stays near 1.0573%. This is useful evidence for a non-temporal floor. Three inspected values do not create fresh held-out validation or certify a broad polynomial relationship.</p><p>This audit covers one fifteen-case survey, not every historical Q2/Q3 campaign. Earlier Q2 temporal/domain studies must be included before scheduling duplicate reference runs. The next physical transfer should use the existing qualified Q2 reference and one controlled Q3 variable, with SF-specific equations, a fixed observation contract and the original speed/shape/tail/constraint gates. Do not transfer the Maxwell numerical order, its field-error tolerance or its periodic conservation outcome into SF acceptance. Q4/Q7 physical motion still requires their original admission gates.</p><h2>Recommended sequence</h2><ol><li>Preserve and archive the new 35-state run, then append this partial-success assessment and failed Hopfion fit to the repository. The previous publication pack targets the parent 61-case run; it does not automatically archive or publish this new run.</li><li>Freeze the packet result as a bounded spatial benchmark. Reprocess existing Hopfion/packet fields to quantify observer quadrature/alignment sensitivity before another large physical campaign.</li><li>Retain the Hopfion failure; after the observer contract is adequate, compare constrained/simple/local fits on development data and reserve a few new physical grids for confirmation. No blanket grid enlargement or tolerance relaxation is justified by this result alone.</li><li>Close the inexpensive duration confirmation only if required for that sub-study, preserving fresh validation and the registered stopping rule.</li><li>Expand the Qx inventory to earlier Q2 evidence, then prepare Q2 qualification and a single Q3 dependency measurement. This can progress as bounded preparation while observer questions are resolved; it does not require another broad topology scan.</li></ol><p>No optimal production mesh is selected because a numerical accuracy/cost objective remains undeclared. Fixed-box convergence is not an isolated-boundary certificate or evidence of particle confinement, charge, quantum spin or an accepted electron model. This assessment does not change source code, run a new physical simulation, or access GitHub.</p>'''
(out/'ASSESSMENT.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dependency continuation assessment</title><style>body{font:16px/1.65 system-ui;max-width:1300px;margin:30px auto;padding:0 20px;color:#18324a}h1,h2{line-height:1.25}svg{width:100%;height:auto}table{border-collapse:collapse;font-size:14px}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}li{margin-bottom:12px}</style>'+body+'</html>')
print(out)
